// Ponte Gestão: traduz { acao, ... } numa chamada às funções srv_* do schema gestao.
const b = $json.body || {};
const nul = v => (v === undefined || v === '' ? null : v);
const exige = (...campos) => { for (const c of campos) if (b[c] === undefined || b[c] === null || b[c] === '') throw new Error(`Ponte Gestão: falta "${c}" para ${b.acao}`); };
let sql, params;
switch (b.acao) {
  case 'pendentes':
    sql = 'select gestao.srv_pendentes_automacao() as r'; params = []; break;
  case 'ler_tarefa':
    exige('tarefa');
    sql = 'select gestao.srv_ler_tarefa($1::uuid) as r'; params = [b.tarefa]; break;
  case 'buscar':
    sql = 'select gestao.srv_buscar_tarefas($1, $2::date, $3::date, $4::boolean) as r';
    params = [nul(b.texto), nul(b.de), nul(b.ate), !!b.incluir_concluidas]; break;
  case 'achar':
    exige('titulo');
    sql = 'select gestao.srv_achar_tarefa($1, $2::boolean) as r'; params = [b.titulo, b.so_abertas === undefined ? true : !!b.so_abertas]; break;
  case 'comentar':
    exige('tarefa', 'texto');
    sql = 'select gestao.srv_comentar($1::uuid, $2, $3) as r'; params = [b.tarefa, b.texto, b.automacao || 'Automação']; break;
  case 'entregar':
    exige('tarefa', 'texto');
    sql = 'select gestao.srv_entregar($1::uuid, $2, $3) as r'; params = [b.tarefa, b.texto, b.automacao || 'Automação']; break;
  case 'criar_peca':
    exige('titulo', 'tipo');
    sql = 'select gestao.srv_criar_peca($1, $2, $3::jsonb, $4, $5::uuid, $6, $7, $8::date) as r';
    params = [b.titulo, b.tipo, JSON.stringify(b.responsaveis || {}), nul(b.notas), nul(b.depende_de), nul(b.cliente), b.area || 'projetos', nul(b.prazo)]; break;
  case 'notas_inicio':
    exige('tarefa', 'linha');
    sql = 'select gestao.srv_notas_inicio($1::uuid, $2, $3) as r'; params = [b.tarefa, b.linha, nul(b.prefixo)]; break;
  case 'garantir_cliente':
    exige('cliente');
    sql = 'select gestao.srv_garantir_cliente($1) as r'; params = [b.cliente]; break;
  case 'importar':
    exige('itens');
    sql = 'select gestao.importar_tarefas($1::jsonb, $2::boolean, true) as r'; params = [JSON.stringify(b.itens), !!b.confirmar]; break; // sem confirmar:true só mostra a prévia (criadas, duplicadas, erros)
  case 'base_ler':
    exige('titulo');
    sql = 'select gestao.srv_base_ler($1, $2) as r'; params = [nul(b.pai), b.titulo]; break;
  case 'base_salvar':
    exige('titulo', 'conteudo');
    sql = 'select gestao.srv_base_salvar($1, $2, $3, $4) as r'; params = [nul(b.pai), b.titulo, b.conteudo, b.modo || 'substituir']; break;
  default:
    throw new Error(`Ponte Gestão: ação desconhecida "${b.acao}". Use pendentes, ler_tarefa, buscar, achar, comentar, entregar, criar_peca, garantir_cliente, notas_inicio, importar, base_ler ou base_salvar.`);
}
return [{ json: { acao: b.acao, sql, params } }];

// Ponte Gestão: resposta enxuta
const pedido = $('Montar chamada').first().json;
const j = $input.first().json;
if (j.error) {
  const e = j.error;
  return [{ json: { ok: false, acao: pedido.acao, erro: (e && (e.description || e.message)) || JSON.stringify(e).slice(0, 300) } }];
}
return [{ json: { ok: true, acao: pedido.acao, resultado: j.r } }];
